const listAHPClientConnectionsForUpdate = `-- name: ListAHPClientConnectionsForUpdate :many
SELECT id, organization_id, project_id, resource_uri, subject_urn, oauth_client_id, active_generation, authorized_at, reauthorized_at, authorization_expires_at, reauthorization_required_at, reauthorization_reason, revoked_at, created_at, updated_at
FROM ahp_connections
WHERE oauth_client_id = $1
  AND revoked_at IS NULL
FOR UPDATE
`

func (q *Queries) ListAHPClientConnectionsForUpdate(ctx context.Context, oauthClientID uuid.UUID) ([]AhpConnection, error) {
	rows, err := q.db.Query(ctx, listAHPClientConnectionsForUpdate, oauthClientID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AhpConnection
	for rows.Next() {
		var i AhpConnection
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ProjectID,
			&i.ResourceUri,
			&i.SubjectUrn,
			&i.OauthClientID,
			&i.ActiveGeneration,
			&i.AuthorizedAt,
			&i.ReauthorizedAt,
			&i.AuthorizationExpiresAt,
			&i.ReauthorizationRequiredAt,
			&i.ReauthorizationReason,
			&i.RevokedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

